 function saveCanvasClauses(clauses){analysisFilters.rules=clauses.flatMap(clause=>clause.values.length?clause.values.map(value=>({key:clause.key,value})):[{key:clause.key,value:''}]);const host=document.querySelector('.canvas-tool-filter');if(host){const openKeys=[...host.querySelectorAll('details[open]')].map(el=>el.closest('.canvas-filter-clause').querySelector('[data-canvas-condition-key]').dataset.canvasConditionKey);host.outerHTML=renderCanvasConditions();for(const clause of document.querySelectorAll('.canvas-filter-clause'))if(openKeys.includes(clause.querySelector('[data-canvas-condition-key]').dataset.canvasConditionKey))clause.querySelector('details').open=true;}updateFilteredAnalysis();persist();}
