 let canvasNodes=[],canvasLinks=[],canvasGroups=[],groupSelection=new Set(),pendingOutput=null,canvasZoom=1,canvasPan={x:0,y:0},wireDrag=null,moduleTemplate=null,canvasImageURLs=new Map(),canvasSaveTimer=null;
