 function saveCanvas(){analysisSettings.analysisCanvas=canvasNodes.map(({frame,element,observer,ready,outputIds,configurationRevision,...node})=>node);analysisSettings.analysisCanvasConnections=structuredClone(canvasLinks);analysisSettings.analysisCanvasGroups=canvasGroups.map(({element,...group})=>structuredClone(group));analysisSettings.analysisCanvasCamera={...canvasPan,zoom:canvasZoom};clearTimeout(canvasSaveTimer);canvasSaveTimer=setTimeout(()=>{canvasSaveTimer=null;persist();},250);}
 window.addEventListener('pagehide',()=>{if(canvasSaveTimer){clearTimeout(canvasSaveTimer);canvasSaveTimer=null;persist();}});
 function canvasSharedPhoto(photo){if(!photo.src?.startsWith('data:'))return photo;let cached=canvasImageURLs.get(photo.id);if(!cached||cached.original!==photo.src){if(cached)URL.revokeObjectURL(cached.url);const comma=photo.src.indexOf(','),header=photo.src.slice(0,comma),raw=atob(photo.src.slice(comma+1)),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);cached={original:photo.src,url:URL.createObjectURL(new Blob([bytes],{type:header.slice(5).split(';')[0]}))};canvasImageURLs.set(photo.id,cached);}return {...photo,src:cached.url};}

 function incoming(node){return canvasLinks.find(link=>link.to===node.id);}
 function inputIds(node){if(node.kind==='data')return photos.map(p=>p.id);const link=incoming(node);return link?(canvasNodes.find(n=>n.id===link.from)?.outputIds||[]):photos.map(p=>p.id);}
