 function configureNode(node){if(!node.ready)return;try{const source=canvasNodes.find(n=>n.id===incoming(node)?.from);if(node.kind==='preview'&&source){if(Array.isArray(source.highlightedIds))node.previewIds=[...source.highlightedIds];else if(hasActiveGraphSelection(source))node.previewIds=[...(source.outputIds||[])];}const ids=new Set(inputIds(node));node.configurationRevision=(node.configurationRevision||0)+1;node.frame.contentWindow.configureCanvasModule({revision:node.configurationRevision,kind:node.kind,brushIds:node.brushIds??null,selectionIds:node.previewIds||[],hasPreviewConnection:directPreviewPeers(node).length>0,maskSources:['preview','gallery'].includes(node.kind)?Object.fromEntries(photos.filter(p=>ids.has(p.id)&&embedded.segmentationMasks?.[p.id]).map(p=>[p.id,canvasSharedPhoto({id:'segmentation-mask:'+p.id,src:embedded.segmentationMasks[p.id].src}).src])):{},photos:photos.filter(p=>ids.has(p.id)).map(canvasSharedPhoto),records,filters:node.filters,settings:node.settings});node.element.classList.remove('canvas-node-error');updatePorts(node);}catch(error){node.element.classList.add('canvas-node-error');node.element.querySelector('.canvas-node-count').textContent='Tool error: '+error.message;}}
 function updatePorts(node){const label=node.element?.querySelector('.canvas-node-count');if(label){label.textContent=inputIds(node).length+' in / '+(node.outputIds?.length||0)+' out';const peers=directVisualPeers(node);label.title=peers.length?'Visual settings linked directly to: '+peers.map(n=>n.title).join(', '):'Independent visual settings';}}
 function visualSettings(node){const graphs=node.filters?.graphs||[],graph=graphs.find(g=>g.colorEnabled)||graphs[0];if(!graph||!['map','analysis'].includes(node.kind))return null;return {attribute:['bar','pie'].includes(graph.type)?graph.attribute||graph.x:graph[graph.colorAxis==='y'?'y':'x'],colorStyle:graph.colorStyle||'gradient',colorEnabled:!!graph.colorEnabled};}
