 function setCanvasZoom(value,clientX,clientY){const viewport=document.querySelector('.canvas-viewport');if(!viewport)return;const r=viewport.getBoundingClientRect(),x=(clientX??r.left+r.width/2)-r.left,y=(clientY??r.top+r.height/2)-r.top,worldX=(x-canvasPan.x)/canvasZoom,worldY=(y-canvasPan.y)/canvasZoom;canvasZoom=Math.min(2,Math.max(.025,value));canvasPan.x=x-worldX*canvasZoom;canvasPan.y=y-worldY*canvasZoom;applyCanvasCamera();}
